      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-skill-picker\",\n  \"description\": \"DSH Web GUI skill picker: a button beside the composer opens a searchable list of installed skills; picking one inserts the official `/skill-name` gesture into the input box, so the skill loads with your message (WorkBuddy-style skill invocation for DeepSeek Harness).\",\n  \"version\": \"0.5.29\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./package.json\": \"./package.json\",\n    \"./locale/*\": \"./locale/*\"\n  },\n  \"scripts\": {\n    \"build\": \"node build.mjs\",\n    \"test\": \"node --test\"\n  },\n  \"devDependencies\": {\n    \"esbuild\": \"^0.25.0\",\n    \"fuzzysort\": \"^4.0.2\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-runtime\",\n        \"@deepseek-ai/dsh-client-locale\"\n      ],\n      \"platform\": \"web\"\n    },\n    \"compatibility\": {\n      \"dshReleases\": {\n        \"0.1.1-rc.1\": \"unknown\",\n        \"0.1.1-rc.2\": \"compatible\",\n        \"0.1.2-alpha.2\": \"compatible\",\n        \"0.1.2-alpha.3\": \"compatible\",\n        \"0.1.2-alpha.4\": \"compatible\",\n        \"0.1.2-alpha.5\": \"compatible\",\n        \"0.1.2-rc.1\": \"compatible\",\n        \"0.1.5-rc.1\": \"compatible\",\n        \"0.1.5-rc.2\": \"compatible\",\n        \"0.1.7-rc.1\": \"unknown\",\n        \"0.1.7-rc.2\": \"unknown\",\n        \"0.2.0-rc.1\": \"compatible\",\n        \"0.2.0-rc.2\": \"compatible\"\n      }\n    }\n  },\n  \"engines\": {\n    \"node\": \">=22\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-client-locale\": \"^0.1.0-rc.6 || >=0.2.0-rc.1 <1.0.0-0\",\n    \"@deepseek-ai/dsh-client-runtime\": \"^0.1.0-rc.6 || >=0.2.0-rc.1 <1.0.0-0\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"^0.1.0-rc.6 || >=0.2.0-rc.1 <1.0.0-0\",\n    \"@deepseek-ai/dsh-host-webserver\": \"^0.1.0-rc.6 || >=0.2.0-rc.1 <1.0.0-0\",\n    \"@deepseek-ai/dsh-skill\": \"^0.1.0-rc.6 || >=0.2.0-rc.1 <1.0.0-0\",\n    \"@deepseek-ai/dsh-system-prompt\": \"^0.1.0-rc.6 || >=0.2.0-rc.1 <1.0.0-0\",\n    \"react\": \"^18.2.0\"\n  },\n  \"files\": [\n    \"lib\",\n    \"src\",\n    \"locale\",\n    \"cordis.patch.yml\",\n    \"docs\",\n    \"README.md\",\n    \"CHANGELOG.md\"\n  ],\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/a735624258/dsh-skill-picker.git\"\n  },\n  \"dependencies\": {\n    \"pinyin-pro\": \"^3.29.3\"\n  }\n}\n"
